CREATE FUNCTION public.pm_billing_invalidate_confirmation() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF (NEW.invoice_description,NEW.amount_value,NEW.vat_rate,NEW.manual_billing_group_id,NEW.planned_invoice_date_override,NEW.planned_payment_date_override,NEW.expected_invoice_date,NEW.expected_payment_date,NEW.stage_id,NEW.trigger_type) IS DISTINCT FROM (OLD.invoice_description,OLD.amount_value,OLD.vat_rate,OLD.manual_billing_group_id,OLD.planned_invoice_date_override,OLD.planned_payment_date_override,OLD.expected_invoice_date,OLD.expected_payment_date,OLD.stage_id,OLD.trigger_type) AND NEW.billing_status::text NOT IN ('issued','paid','cancelled') THEN UPDATE pm_invoice_readiness SET confirmed_at=NULL WHERE payment_item_id=NEW.id OR (NEW.manual_billing_group_id IS NOT NULL AND payment_item_id IN(SELECT id FROM pm_payment_schedule_items WHERE manual_billing_group_id=NEW.manual_billing_group_id)); END IF;RETURN NEW;END $$;
CREATE TRIGGER pm_billing_invalidate_confirmation AFTER UPDATE ON public.pm_payment_schedule_items FOR EACH ROW EXECUTE FUNCTION public.pm_billing_invalidate_confirmation();
DO $$ DECLARE d text;BEGIN SELECT pg_get_functiondef('public.pm_billing_plan(uuid)'::regprocedure) INTO d;d:=replace(d,$a$'direction',p.direction,$a$,$b$'direction',p.direction,'billing_status',CASE WHEN EXISTS(SELECT 1 FROM financial_document_lines dl JOIN financial_documents fd ON fd.id=dl.document_id WHERE dl.payment_schedule_item_id=p.id AND fd.status::text NOT IN ('draft','cancelled')) THEN CASE WHEN NOT EXISTS(SELECT 1 FROM financial_document_lines dl JOIN financial_documents fd ON fd.id=dl.document_id WHERE dl.payment_schedule_item_id=p.id AND fd.status::text NOT IN ('draft','cancelled') AND fd.status::text<>'paid') THEN 'paid' ELSE 'issued' END ELSE p.billing_status::text END,$b$);EXECUTE d;END $$;